function pickRendition(renditions, measuredKbps, bufferSeconds) {
  const budget = measuredKbps * (bufferSeconds < 10 ? 0.5 : 0.8);
  const sorted = [...renditions].sort((a, b) => b.kbps - a.kbps);
  return sorted.find((r) => r.kbps <= budget) ?? sorted[sorted.length - 1];
}

const ladder = [{ name: "1080p", kbps: 5000 }, { name: "360p", kbps: 700 }, { name: "720p", kbps: 2500 }];
pickRendition(ladder, 4000, 25).name; // "720p" (budget 3200)
pickRendition(ladder, 4000, 4).name;  // "360p" (budget 2000)
pickRendition(ladder, 500, 30).name;  // "360p" (fallback)
```
